import{boot,e,field,editAttrs}from'../creative-kit/ui.js?v=0.9.0';import{make,validate,apply,markdown,depth,FIELDS}from'./state.js?v=0.9.0';
function card(n){return `<article class="card concept ${n.parked?'parked':''}" data-drag-id="${e(n.id)}"><div class="card-top"><span>${n.parents.length===2?'Combination':n.parents.length?'Branch':'Original'}${n.parked?' · parked':''}</span><button class="drag-handle" data-drag-handle data-action="compare-menu" data-id="${e(n.id)}" aria-label="Compare ${e(n.title)}">⠿</button></div><h3>${e(n.title)}</h3><p>${e(n.mechanism||'Describe the working mechanism.')}</p>${n.sources.length?`<div class="ancestry">From ${n.sources.map(s=>`<button data-action="edit" data-id="${e(s.id)}">${e(s.title)}</button>`).join(' + ')}</div>`:''}<div class="card-actions"><button class="text-button" data-action="edit" data-id="${e(n.id)}">Develop</button><button class="text-button" data-action="fork" data-id="${e(n.id)}">Fork ↗</button><button class="text-button" data-action="compare-menu" data-id="${e(n.id)}">Compare</button></div></article>`;}
function render(w){const levels=Math.max(...w.nodes.map(n=>depth(w,n.id)))+1;return `<div class="section-head"><div><h2>Keep the ancestry of the idea.</h2><p>Fork to change an ingredient. Compare two branches before combining what is useful.</p></div><button data-action="root" ${w.nodes.length>=24?'disabled':''}>+ Independent concept</button></div><p class="hint">Scroll sideways through generations. Compare opens a choice of slots without dragging.</p><div class="family-scroll" tabindex="0" aria-label="Idea ancestry, arranged by generation"><div class="family-levels" style="--levels:${levels}">${Array.from({length:levels},(_,level)=>`<section class="generation"><h2>${level===0?'Starting points':`Generation ${level}`}</h2>${w.nodes.filter(n=>depth(w,n.id)===level).map(card).join('')}</section>`).join('')}</div></div><section id="compare" class="comparison"><div class="section-head"><div><h2>What did this branch change?</h2><p>Drag two concepts into the comparison slots, or use Compare. Source snapshots preserve the reasoning at the time of a fork.</p></div><button class="primary" data-action="combine" ${w.compare.some(x=>!x)||w.nodes.length>=24?'disabled':''}>Combine these branches ↗</button></div><div class="two-col">${w.compare.map((id,slot)=>{const n=w.nodes.find(n=>n.id===id);return `<section class="compare-slot panel" data-drop-id="${slot}"><div class="card-top"><span>${slot===0?'Left branch':'Right branch'}</span>${n?`<button class="text-button" data-action="clear" data-slot="${slot}">Clear</button>`:''}</div>${n?`<h3>${e(n.title)}</h3>${['mechanism','benefit','changed','why','test'].map(f=>`<div class="comparison-field"><span>${f==='why'?'REASON FOR CHANGE':f.toUpperCase()}</span><p>${e(n[f]||'Not written yet.')}</p></div>`).join('')}<button data-action="edit" data-id="${e(n.id)}">Edit this concept</button>`:'<div class="empty">Drop a concept here.</div>'}</section>`;}).join('')}</div></section>`;}
function edit(id,k){const n=k.w().nodes.find(n=>n.id===id),labels={title:'Concept name',mechanism:'How does it work?',benefit:'What useful outcome does it protect?',ingredients:'Which ingredients does it use?',changed:'What changed from its parent?',why:'Why make that change?',test:'What would you try or observe?'};k.open(FIELDS.map(f=>field(`node-${f}`,labels[f],n[f],editAttrs('nodes',id,f))).join('')+(n.sources.length?`<details><summary>Source wording when this branch was created</summary>${n.sources.map(s=>`<h3>${e(s.title)}</h3><p>${e(s.mechanism)}</p>`).join('')}</details>`:'')+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button data-action="park" data-id="${e(id)}">${n.parked?'Revive':'Park'} this concept</button><button class="delete" data-action="remove" data-id="${e(id)}" ${k.w().nodes.length===1||k.w().nodes.some(x=>x.parents.includes(id))?'disabled':''}>Delete leaf</button></div><p class="hint">Later parent edits do not change the children. Park ancestors to keep their history visible.</p>`,'Develop a branch');}
boot({route:'family',code:'S10',title:'Idea family tree',description:'Keep alternatives connected without losing the differences that make them useful.',make,validate,apply,markdown,render,drop:(id,slot,k)=>k.act({type:'compare',id,slot}),handle:(a,d,k)=>{if(a==='edit')edit(d.id,k);else if(['fork','combine','root'].includes(a)){const id=k.uid();if(k.act({type:a,id,parent:d.id}))edit(id,k);}else if(a==='compare-menu')k.open(`<div class="dialog-options"><button data-action="place" data-id="${e(d.id)}" data-slot="0">Compare on the left</button><button data-action="place" data-id="${e(d.id)}" data-slot="1">Compare on the right</button></div>`,'Compare a concept');else if(a==='place'){k.close();k.act({type:'compare',id:d.id,slot:d.slot});}else if(['park','remove'].includes(a)){k.close();k.act({type:a,id:d.id});}else if(a==='clear')k.act({type:a,slot:d.slot});}});
